parameters.jsCode:
const s = $('Set search settings').first().json;
const flag = (v) => v !== false && v !== 'false' && v !== 0 && v !== '0';
const requireAuth = flag(s.requireActiveAuthority);
const requireContact = flag(s.requireContact);
const isActive = (v) => String(v || '').trim().toLowerCase() === 'active';

const out = [];
for (const item of $input.all()) {
  const c = item.json || {};
  if (c.dotNumber == null && !c.legalName) continue;

  if (requireAuth) {
    const hasAuth = isActive(c.commonAuthority) || isActive(c.contractAuthority) || isActive(c.brokerAuthority);
    if (!hasAuth) continue;
  }

  if (requireContact) {
    const phone = String(c.phone || c.cellPhone || '').trim();
    const email = String(c.email || '').trim();
    if (!phone && !email) continue;
  }

  out.push({ json: c });
}
return out;

const logged = new Set(
  $('Get existing USDOT numbers').all()
    .map((i) => String(i.json.dotNumber ?? '').trim())
    .filter(Boolean)
);
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const c = item.json || {};
  const dot = String(c.dotNumber ?? '').trim();
  if (!dot || logged.has(dot) || seen.has(dot)) continue;
  seen.add(dot);
  out.push({ json: c });
}
return out;

const carriers = $input.all()
  .map((i) => i.json)
  .filter((j) => j && j.dotNumber != null && String(j.dotNumber).trim() !== '');

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const authLabel = (c) => {
  const parts = [];
  if (String(c.commonAuthority || '').toLowerCase() === 'active') parts.push('common');
  if (String(c.contractAuthority || '').toLowerCase() === 'active') parts.push('contract');
  if (String(c.brokerAuthority || '').toLowerCase() === 'active') parts.push('broker');
  return parts.join(', ') || 'none';
};

const rows = carriers.slice(0, 50).map((c) => {
  const dot = esc(c.dotNumber);
  const safer = c.saferUrl ? `<a href="${esc(c.saferUrl)}">${dot}</a>` : dot;
  return `<tr>
    <td style="padding:6px;border-bottom:1px solid #eee">${safer}</td>
    <td style="padding:6px;border-bottom:1px solid #eee">${esc(c.legalName)}</td>
    <td style="padding:6px;border-bottom:1px solid #eee">${esc(c.city)}, ${esc(c.state)}</td>
    <td style="padding:6px;border-bottom:1px solid #eee">${esc(c.phone)}</td>
    <td style="padding:6px;border-bottom:1px solid #eee">${esc(c.email)}</td>
    <td style="padding:6px;border-bottom:1px solid #eee">${esc(authLabel(c))}</td>
  </tr>`;
}).join('');

const count = carriers.length;
const digestHtml = `<p style="font-family:Arial,sans-serif;font-size:14px">Today's run found <b>${count}</b> new carrier${count === 1 ? '' : 's'} that passed your filters and were not already in your sheet.</p>
<table style="font-family:Arial,sans-serif;font-size:13px;border-collapse:collapse;width:100%">
  <thead><tr>
    <th style="text-align:left;padding:6px;border-bottom:2px solid #333">USDOT</th>
    <th style="text-align:left;padding:6px;border-bottom:2px solid #333">Legal name</th>
    <th style="text-align:left;padding:6px;border-bottom:2px solid #333">City, ST</th>
    <th style="text-align:left;padding:6px;border-bottom:2px solid #333">Phone</th>
    <th style="text-align:left;padding:6px;border-bottom:2px solid #333">Email</th>
    <th style="text-align:left;padding:6px;border-bottom:2px solid #333">Active authority</th>
  </tr></thead>
  <tbody>${rows}</tbody>
</table>
<p style="font-family:Arial,sans-serif;color:#666;font-size:12px">Showing up to 50 rows. All new carriers were appended to your Google Sheet.</p>`;

return [{ json: { carriers, count, digestHtml } }];
